function ensureTreeImport(){
  if(!archiveData.relationships)archiveData.relationships=[];
  const ids=new Set(archiveData.people.map(p=>p.id));
  treeImportPeople.forEach(p=>{if(!ids.has(p.id))archiveData.people.push({...p})});
  const rids=new Set(archiveData.relationships.map(r=>r.id));
  treeImportRelationships.forEach(r=>{if(!rids.has(r.id))archiveData.relationships.push({...r})});
  archiveData.treeImportVersion=TREE_IMPORT_VERSION;
}
