const STORAGE_KEY="tiwh_archive_v3";
let submissions=[];

function loadLocalArchive(){
  try{
    const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||"null");
    if(saved&&saved.archiveData){
      Object.keys(saved.archiveData||{}).forEach(k=>{
        if(Array.isArray(saved.archiveData[k])){
          if(k==="photos" && saved.archiveData[k].length===0 && archiveData.photos.length>0) return;
          archiveData[k]=saved.archiveData[k];
        }
      }); ensureTreeImport();
      submissions=Array.isArray(saved.submissions)?saved.submissions:[];
    }
  }catch(e){console.warn("Could not load local archive",e)}
}
function saveLocalArchive(){
  try{
    localStorage.setItem(STORAGE_KEY,JSON.stringify({archiveData,submissions,updated:new Date().toISOString()}));
  }catch(e){
    console.warn("Could not save local archive",e);
  }
  refreshCounts();
}
function refreshCounts(){
  const box=document.getElementById("countGrid");
  if(box)box.innerHTML=archiveCounts().map(x=>`<div class="count"><b>${x[0]}</b><span>${x[1]}</span></div>`).join("");
}
function safeText(v){return String(v||"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]))}
function parseYear(v){const m=String(v||"").match(/\d{4}/);return m?Number(m[0]):new Date().getFullYear()}
function readImage(file){
  return new Promise(resolve=>{
    if(!file)return resolve("");
    const reader=new FileReader();
    reader.onload=()=>resolve(reader.result);
    reader.onerror=()=>resolve("");
    reader.readAsDataURL(file);
  });
}
async function saveDiscoveryFromForm(){
  const file=document.getElementById("dImage").files[0];
  const image=await readImage(file);
  const item={
    id:"d-"+Date.now(),
    type:document.getElementById("dType").value,
    family:document.getElementById("dFamily").value,
    title:document.getElementById("dTitle").value.trim(),
    date:document.getElementById("dDate").value.trim(),
    year:parseYear(document.getElementById("dDate").value),
    place:document.getElementById("dPlace").value.trim(),
    category:document.getElementById("dCategory").value.trim(),
    details:document.getElementById("dDetails").value.trim(),
    status:document.getElementById("dStatus").value,
    source:document.getElementById("dSource").value.trim(),
    questions:document.getElementById("dQuestions").value.trim(),
    image,
    reviewStatus:"Pending review",
    created:new Date().toISOString()
  };
  if(!item.title){document.getElementById("saveStatus").textContent="Add a name or title before saving.";return}
  submissions.unshift(item);saveLocalArchive();renderReviewQueue();
  document.getElementById("saveStatus").textContent="Saved to the Research Desk on this device.";
  ["dTitle","dDate","dPlace","dCategory","dDetails","dSource","dQuestions"].forEach(id=>document.getElementById(id).value="");
  document.getElementById("dImage").value="";
}
function renderReviewQueue(){
  const box=document.getElementById("reviewList");if(!box)return;
  if(!submissions.length){box.innerHTML='<div class="empty-state">No discoveries are waiting for review.</div>';return}
  box.innerHTML=submissions.map(s=>`<article class="review-card">
    <div class="review-meta"><span class="review-pill">${safeText(s.reviewStatus)}</span><span class="review-pill">${safeText(s.type)}</span><span class="review-pill">${safeText(s.family)}</span><span class="review-pill">${safeText(s.status)}</span></div>
    <h4>${safeText(s.title)}</h4>
    <p>${safeText(s.date)}${s.place?" · "+safeText(s.place):""}</p>
    <p>${safeText(s.details)}</p>
    ${s.source?`<p><strong>Source:</strong> ${safeText(s.source)}</p>`:""}
    ${s.questions?`<p><strong>Review notes:</strong> ${safeText(s.questions)}</p>`:""}
    ${s.image?`<img class="preview-image" src="${s.image}" alt="">`:""}
    <div class="review-actions">
      <button class="action-btn primary" onclick="publishDiscovery('${s.id}')">Publish everywhere</button>
      <button class="action-btn" onclick="returnDiscovery('${s.id}')">Needs more research</button>
      <button class="action-btn" onclick="deleteDiscovery('${s.id}')">Delete draft</button>
    </div></article>`).join("");
}
function publishDiscovery(id){
  const s=submissions.find(x=>x.id===id);if(!s)return;
  if(s.type==="person"){
    archiveData.people.push({id:s.id,name:s.title,family:s.family,generation:null,date:s.date,place:s.place,details:s.details,status:s.status==="Documented fact"?"Confirmed":"Possible",source:s.source,category:s.category,occupation:s.category,image:s.image});
  }
  if(s.type==="photo"){
    archiveData.photos.push({id:s.id,title:s.title,family:s.family,date:s.date,place:s.place,details:s.details,status:s.status,source:s.source,image:s.image,category:s.category});
  }
  if(s.type==="place"){
    archiveData.places.push({id:s.id,name:s.place||s.title,family:s.family,lat:null,lng:null,year:s.year,status:s.status,event:s.title,evidence:s.details,category:s.category,google:s.place?`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.place)}`:""});
  }
  if(s.type==="story"){
    archiveData.stories.push({id:s.id,title:s.title,family:s.family,status:s.status,date:s.date,details:s.details,source:s.source,image:s.image,category:s.category,place:s.place});
  }
  if(s.type==="source"){
    archiveData.sources.push({id:s.id,title:s.title,family:s.family,date:s.date,details:s.details,status:s.status,source:s.source,image:s.image,category:s.category,place:s.place});
  }
  if(s.type==="livelihood"){
    if(!archiveData.livelihoods)archiveData.livelihoods=[];
    archiveData.livelihoods.push({id:s.id,title:s.title,family:s.family,category:s.category||s.title,details:s.details,date:s.date,place:s.place,status:s.status,people:[]});
  }
  if(s.type==="mystery")archiveData.mysteries.push(s.title+(s.details?": "+s.details:""));
  s.reviewStatus="Published";
  submissions=submissions.filter(x=>x.id!==id);
  saveLocalArchive();renderReviewQueue();
}
function returnDiscovery(id){
  const s=submissions.find(x=>x.id===id);if(s){s.reviewStatus="Needs more research";saveLocalArchive();renderReviewQueue()}
}
function deleteDiscovery(id){
  submissions=submissions.filter(x=>x.id!==id);saveLocalArchive();renderReviewQueue();
}
function exportArchive(){
  const blob=new Blob([JSON.stringify({archiveData,submissions,exported:new Date().toISOString()},null,2)],{type:"application/json"});
  const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="this-is-what-happened-archive-backup.json";a.click();URL.revokeObjectURL(a.href);
}
function importArchive(file){
  const reader=new FileReader();
  reader.onload=()=>{
    try{
      const data=JSON.parse(reader.result);
      if(data.archiveData){Object.keys(data.archiveData||{}).forEach(k=>{if(Array.isArray(data.archiveData[k]))archiveData[k]=data.archiveData[k]}); ensureTreeImport()}
      submissions=Array.isArray(data.submissions)?data.submissions:[];
      saveLocalArchive();renderReviewQueue();document.getElementById("saveStatus").textContent="Backup imported.";
    }catch(e){document.getElementById("saveStatus").textContent="That file could not be imported."}
  };
  reader.readAsText(file);
}
function initDiscoveryDesk(){
  renderReviewQueue();
  document.getElementById("saveDiscovery").onclick=saveDiscoveryFromForm;
  document.getElementById("exportArchive").onclick=exportArchive;
  document.getElementById("importArchive").onchange=e=>{if(e.target.files[0])importArchive(e.target.files[0])};
}
loadLocalArchive(); refreshCounts();


function addDiscoveryFor(type,family="",category=""){
  openRoom("discovery");
  setTimeout(()=>{
    const t=document.getElementById("dType"),f=document.getElementById("dFamily"),c=document.getElementById("dCategory");
    if(t)t.value=type;if(f&&family&&archiveData.families.includes(family))f.value=family;if(c&&category)c.value=category;
  },80);
}
function familyRecords(family){
  return {
    people:archiveData.people.filter(x=>x.family===family),
    photos:archiveData.photos.filter(x=>x.family===family),
    places:archiveData.places.filter(x=>x.family===family),
    stories:archiveData.stories.filter(x=>x.family===family),
    sources:archiveData.sources.filter(x=>x.family===family),
    livelihoods:(archiveData.livelihoods||[]).filter(x=>x.family===family||x.family==="All families")
  };
}
function familySummary(f){
  return {
    Zahner:["Baden origins and American chapters","Mining, farming, aviation, movement, and family enterprise."],
    Downing:["Working lives and communities","Factory workers, farmers, laborers, households, and practical family life."],
    Blackwell:["Faith, land, and public life","Preachers, public figures, farming, property, influence, and carefully researched history."],
    Barrett:["Trades, businesses, and relationships","Business, farming, family relationships, and Bill Barrett’s decades behind the barber chair."]
  }[f];
}
function lifespan(p){
  if(p.living)return `${p.birth||"Year unknown"}–Living`;
  if(p.birth||p.death)return `${p.birth||"?"}–${p.death||"?"}`;
  return "Dates not yet transcribed";
}
function statusClass(s){return "status-"+String(s||"Possible").toLowerCase().replace(/\s+/g,"-")}

