function openPersonRecord(personId){
  const p=archiveData.people.find(x=>x.id===personId); if(!p)return;
  const page=PERSON_PAGES[p.name];
  if(page){window.location.href=page;return;}
  const box=document.getElementById("familyDetail");
  box.innerHTML=`<section class="detail-panel"><small>${safeText(p.family)} · Generation ${safeText(p.generation??"not assigned")}</small><h3>${safeText(p.name)}</h3><p><strong>${lifespan(p)}</strong></p><p>${safeText(p.notes||p.occupation||"A full biography has not yet been written. This record remains available for photographs, sources, memories, and corrections.")}</p><div class="detail-section"><strong>Evidence</strong><p>${safeText(p.source||"No source recorded")}</p><span class="evidence-mini ${statusClass(p.status)}">${safeText(p.status||"Possible")}</span></div></section>`;
  box.scrollIntoView({behavior:"smooth",block:"start"});
}

function familyPeople(f){return archiveData.people.filter(p=>p.family===f).sort((a,b)=>(b.generation??-99)-(a.generation??-99)||(a.birth||9999)-(b.birth||9999))}
function familyRelationships(f){
  const ids=new Set(familyPeople(f).map(p=>p.id));
  return (archiveData.relationships||[]).filter(r=>ids.has(r.personId)||ids.has(r.relatedId));
}
function gapStats(f){
  const people=familyPeople(f), rels=familyRelationships(f);
  return {
    people:people.length,
    generations:new Set(people.map(p=>p.generation).filter(x=>x!==null&&x!==undefined)).size,
    placeholders:people.filter(p=>p.status==="Placeholder").length,
    unconfirmed:people.filter(p=>p.status!=="Confirmed").length,
    missingBirth:people.filter(p=>!p.birth).length,
    missingDeath:people.filter(p=>!p.living&&!p.death).length,
    relationships:rels.length,
    unconfirmedRelationships:rels.filter(r=>r.status!=="Confirmed").length
  };
}
