  const app=document.getElementById("storiesApp");if(!app)return;
  app.innerHTML=`<div class="collection-toolbar"><button class="filter-btn active" data-sf="All">All</button>${archiveData.families.map(f=>`<button class="filter-btn" data-sf="${f}">${f}</button>`).join("")}</div><div id="storyGrid"></div><div id="storyDetail"></div>`;
  app.querySelectorAll("[data-sf]").forEach(b=>b.onclick=()=>{app.querySelectorAll("[data-sf]").forEach(x=>x.classList.remove("active"));b.classList.add("active");renderStories(b.dataset.sf)});
