function showStory(i){
  const s=archiveData.stories[i],box=document.getElementById("storyDetail");if(!s||!box)return;
  const text=s.details||"This story has a title but its narrative has not been entered yet.";
  box.innerHTML=`<section class="detail-panel"><small>${safeText(s.family)} · ${safeText(s.status||"Draft")}</small><h3>${safeText(s.title)}</h3><p id="storyNarrative">${safeText(text)}</p><div class="detail-section"><strong>Source and evidence</strong><p>${safeText(s.source||"No source recorded yet.")}</p></div><div class="audio-controls"><button class="action-btn primary" onclick="speakStory(${i})">Listen</button><button class="action-btn" onclick="speechSynthesis.cancel()">Stop</button><button class="action-btn" onclick="addDiscoveryFor('source','${safeText(s.family)}')">Add evidence</button></div></section>`;
  box.scrollIntoView({behavior:"smooth",block:"start"});
}
function speakStory(i){
  if(!("speechSynthesis" in window))return alert("Browser narration is not available on this device.");
  const s=archiveData.stories[i];speechSynthesis.cancel();const u=new SpeechSynthesisUtterance((s.title+". "+(s.details||"")));u.rate=.9;speechSynthesis.speak(u);
}
function archiveCollections(){
  return [
    ["people","People",archiveData.people],
    ["sources","Sources",archiveData.sources],
    ["photos","Photographs",archiveData.photos],
    ["places","Places",archiveData.places],
    ["stories","Stories",archiveData.stories],
    ["livelihoods","Livelihoods",archiveData.livelihoods||[]],
    ["relationships","Relationships",archiveData.relationships||[]],
    ["mysteries","Mysteries",archiveData.mysteries]
  ];
}
function initArchive(){
  const app=document.getElementById("archiveApp");if(!app)return;
  app.innerHTML=`<div class="searchbar"><input id="archiveSearch" placeholder="Search people, places, stories, sources, photographs, and livelihoods"></div><div class="archive-sections">${archiveCollections().map(([k,n,a])=>`<button class="archive-section-btn" onclick="showArchiveCollection('${k}')"><strong>${n}</strong><span>${a.length} loaded</span></button>`).join("")}</div><div id="archiveResults"></div>`;
  document.getElementById("archiveSearch").oninput=e=>searchArchive(e.target.value);
}
function normalizedArchiveRecords(){
  const rows=[];
  archiveCollections().forEach(([type,name,arr])=>arr.forEach((x,i)=>{
    const obj=typeof x==="string"?{title:x}:x;
    let title=obj.name||obj.title||obj.event||"Untitled";
    let details=obj.details||obj.evidence||obj.source||obj.category||"";
    if(type==="relationships"){const a=archiveData.people.find(p=>p.id===obj.personId),b=archiveData.people.find(p=>p.id===obj.relatedId);title=`${a?.name||"Unknown"} → ${b?.name||"Unknown"}`;details=`${obj.type||"relationship"} · ${obj.status||"Possible"}`;}
    rows.push({type,name,index:i,title,family:obj.family||"",details,raw:obj});
  }));
  return rows;
}
function searchArchive(q){
  const box=document.getElementById("archiveResults");q=q.trim().toLowerCase();
  if(!q){box.innerHTML="";return}
  const rows=normalizedArchiveRecords().filter(r=>(r.title+" "+r.family+" "+r.details+" "+r.name).toLowerCase().includes(q));
  box.innerHTML=rows.length?`<div class="record-grid" style="margin-top:14px">${rows.map(r=>`<button class="record-card" onclick="showArchiveRecord('${r.type}',${r.index})"><small>${r.name} · ${safeText(r.family)}</small><h3>${safeText(r.title)}</h3><p>${safeText(r.details)}</p></button>`).join("")}</div>`:`<div class="empty-collection" style="margin-top:14px">No matching records.</div>`;
}
function showArchiveCollection(type){
  const box=document.getElementById("archiveResults"),col=archiveCollections().find(x=>x[0]===type),arr=col[2];
  box.innerHTML=arr.length?`<div class="record-grid" style="margin-top:14px">${arr.map((x,i)=>{const o=typeof x==="string"?{title:x}:x;return `<button class="record-card" onclick="showArchiveRecord('${type}',${i})">${o.image?`<img src="${o.image}" alt="${safeText(o.title||'Family photograph')}">`:""}<small>${safeText(o.family||col[1])}</small><h3>${safeText(o.name||o.title||o.event||"Untitled")}</h3><p>${safeText(o.details||o.evidence||o.source||o.category||"")}</p></button>`}).join("")}</div>`:`<div class="empty-collection" style="margin-top:14px">No ${col[1].toLowerCase()} have been loaded yet.<div class="inline-actions" style="justify-content:center"><button class="action-btn primary" onclick="addDiscoveryFor('${type==="photos"?"photo":type==="people"?"person":type==="livelihoods"?"livelihood":type==="mysteries"?"mystery":type.slice(0,-1)}')">Add one</button></div></div>`;
  box.scrollIntoView({behavior:"smooth",block:"start"});
}
function showArchiveRecord(type,i){
  const col=archiveCollections().find(x=>x[0]===type),x=col[2][i],o=typeof x==="string"?{title:x}:x,box=document.getElementById("archiveResults");
  box.innerHTML=`<section class="detail-panel"><small>${safeText(col[1])} · ${safeText(o.family||"")}</small><h3>${safeText(o.name||o.title||o.event||"Untitled")}</h3>${o.image?`<img class="preview-image" src="${o.image}" alt="">`:""}<p>${safeText(o.details||o.evidence||o.source||o.category||"No additional description.")}</p><div class="detail-section"><strong>Status</strong><p>${safeText(o.status||"Not assigned")}</p></div><div class="inline-actions"><button class="action-btn" onclick="addDiscoveryFor('source','${safeText(o.family||"")}')">Add supporting source</button><button class="action-btn" onclick="initArchive()">Back to archive</button></div></section>`;
}

let familyMap=null;
let markerLayer=null;

function markerColor(family){
  return {Zahner:"#88a7b8",Downing:"#a6b65d",Blackwell:"#c86a4b",Barrett:"#d3a04f"}[family]||"#c39850";
}

function initFamilyMap(){
  const mapEl=document.getElementById("familyMap");
  const loading=document.getElementById("mapLoading");
  const retry=document.getElementById("mapRetry");
  if(!mapEl)return;

  const showFailure=()=>{
    if(loading){
      loading.classList.remove("hidden");
      loading.querySelector("strong").textContent="The map is taking longer than expected.";
      const span=loading.querySelector("span");
      if(span)span.textContent="The location cards below are still available. Tap retry to load the map again.";
      if(retry)retry.style.display="inline-block";
    }
  };

  if(retry)retry.onclick=()=>{ if(familyMap){familyMap.remove();familyMap=null;} initFamilyMap(); };

  if(typeof L==="undefined"){
    showFailure();
    renderMapRecords(archiveData.places);
    return;
  }

  if(familyMap){familyMap.remove();familyMap=null;}

  familyMap=L.map("familyMap",{
    worldCopyJump:true,
    zoomControl:true,
    attributionControl:true,
    preferCanvas:true
  }).setView([42,-35],2);

  const tiles=L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{
    maxZoom:19,
    updateWhenIdle:false,
    keepBuffer:3,
    crossOrigin:true,
    attribution:'&copy; OpenStreetMap contributors'
  });

  let tileLoaded=false;
  tiles.on("load",()=>{
    tileLoaded=true;
    if(loading)loading.classList.add("hidden");
    setTimeout(()=>familyMap&&familyMap.invalidateSize({pan:false}),50);
  });
  tiles.on("tileerror",()=>{ if(!tileLoaded)showFailure(); });
  tiles.addTo(familyMap);

  markerLayer=L.layerGroup().addTo(familyMap);

  const year=document.getElementById("mapYear");
  if(year)year.addEventListener("input",()=>{
    const v=document.getElementById("mapYearValue");
    if(v)v.textContent=year.value;
    updateFamilyMap();
  });
  document.querySelectorAll(".map-family-filter").forEach(box=>box.addEventListener("change",updateFamilyMap));

  updateFamilyMap();

  const repair=()=>{
    if(!familyMap)return;
    familyMap.invalidateSize({pan:false,animate:false});
    updateFamilyMap();
  };

  [80,220,500,900,1500].forEach(ms=>setTimeout(repair,ms));

  if("ResizeObserver" in window){
    window._familyMapObserver?.disconnect?.();
    window._familyMapObserver=new ResizeObserver(()=>setTimeout(repair,40));
    window._familyMapObserver.observe(mapEl);
  }

  window.removeEventListener("orientationchange",window._familyMapOrientationRepair||(()=>{}));
  window._familyMapOrientationRepair=()=>setTimeout(repair,350);
  window.addEventListener("orientationchange",window._familyMapOrientationRepair);

  setTimeout(()=>{if(!tileLoaded)showFailure()},5000);
}

function filteredPlaces(){
  const active=[...document.querySelectorAll(".map-family-filter:checked")].map(x=>x.value);
  const year=Number(document.getElementById("mapYear")?.value||2026);
  return archiveData.places.filter(p=>active.includes(p.family)&&p.year<=year);
}

function updateFamilyMap(){
  if(!familyMap||!markerLayer)return;
  markerLayer.clearLayers();
  const places=filteredPlaces();
  const mappable=places.filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lng));
  const bounds=[];
  mappable.forEach(p=>{
    const icon=L.divIcon({
      className:"",
      html:`<span style="display:block;width:18px;height:18px;border-radius:50%;background:${markerColor(p.family)};border:3px solid #17110d;box-shadow:0 2px 8px rgba(0,0,0,.45)"></span>`,
      iconSize:[18,18],iconAnchor:[9,9]
    });
    const marker=L.marker([p.lat,p.lng],{icon}).addTo(markerLayer);
    marker.bindPopup(`<strong>${p.name}</strong><br>${p.year} · ${p.family}<br>${p.event}<br><em>${p.status}</em><br><a href="${p.google}" target="_blank" rel="noopener">View in Google Maps</a>`);
    bounds.push([p.lat,p.lng]);
  });
  if(bounds.length===1)familyMap.setView(bounds[0],7);
  else if(bounds.length>1)familyMap.fitBounds(bounds,{padding:[30,30],maxZoom:6});
  renderMapRecords(places);
}

function renderMapRecords(places){
  const box=document.getElementById("mapRecords");
  if(!box)return;
  box.innerHTML=places.length?places.map(p=>`
    <article class="map-record-card">
      <span class="status-pill">${p.status}</span>
      <h4>${p.name}</h4>
      <p><strong>${p.year} · ${p.family}</strong></p>
      <p>${p.event}</p>
      <p>${p.evidence}</p>
      <a href="${p.google}" target="_blank" rel="noopener">View the real place in Google Maps</a>
    </article>`).join(""):'<article class="map-record-card"><h4>No places shown</h4><p>Adjust the family filters or timeline.</p></article>';
}

const entranceView=document.getElementById("entrance");
const roomView=document.getElementById("room");

function openRoom(key){
  const d=rooms[key];
  if(!d || !entranceView || !roomView)return;
  document.getElementById("roomKicker").textContent=d.k;
  document.getElementById("roomTitle").textContent=d.t;
  document.getElementById("roomIntro").textContent=d.i;
  document.getElementById("roomContent").innerHTML=d.c;
  entranceView.classList.remove("active-view");
  roomView.classList.add("active-view");
  document.body.style.overflowY="auto";
  history.replaceState(null,"","#"+key);
  window.scrollTo({top:0,behavior:"auto"});
  if(key==="families") setTimeout(initFamilies,50);
  if(key==="wanderings") setTimeout(initFamilyMap,180);
  if(key==="album") setTimeout(initPhotographs,50);
  if(key==="livelihoods") setTimeout(initLivelihoods,50);
  if(key==="stories") setTimeout(initStories,50);
  if(key==="archive") setTimeout(initArchive,50);
  if(key==="discovery") setTimeout(initDiscoveryDesk,50);
}
let lastTouchActivation=0;
function activateRoomControl(control){
  if(!control)return;
  const key=control.dataset.room || (control.dataset.family ? "families" : "");
  if(!key)return;
  openRoom(key);
  if(control.dataset.family)setTimeout(()=>showFamily(control.dataset.family),80);
}

document.addEventListener("click",event=>{
  if(Date.now()-lastTouchActivation<700)return;
  const control=event.target.closest("[data-room],[data-family]");
  if(!control)return;
  event.preventDefault();
  activateRoomControl(control);
});

document.addEventListener("pointerup",event=>{
  if(event.pointerType!=="touch")return;
  const control=event.target.closest("[data-room],[data-family]");
  if(!control)return;
  event.preventDefault();
  lastTouchActivation=Date.now();
  activateRoomControl(control);
});

document.getElementById("backButton").addEventListener("click",()=>{
  roomView.classList.remove("active-view");
  entranceView.classList.add("active-view");
  history.replaceState(null,"",location.pathname);
  window.scrollTo({top:0,behavior:"auto"});
});
const hash=location.hash.slice(1);
if(rooms[hash])openRoom(hash);

// Homepage family-map invitation: reuse the existing family navigation behavior.
document.querySelectorAll("[data-map-family]").forEach((button) => {
  button.addEventListener("click", () => {
    const family = button.dataset.mapFamily;
    const target = [...document.querySelectorAll(".journal-shelf [data-family]")]
      .find((candidate) => candidate.dataset.family === family);
    if (target) target.click();
  });
});
